func literalResolutionValues(file *ast.File) map[string]bool {
 found := map[string]bool{}
 var constantString func(ast.Expr, map[ast.Expr]bool) (string, bool)
 constantString = func(expr ast.Expr, seen map[ast.Expr]bool) (string, bool) {
  if expr == nil || seen[expr] { return "", false }; seen[expr] = true
  switch x := expr.(type) {
  case *ast.BasicLit:
   if x.Kind == token.STRING { value, err := strconv.Unquote(x.Value); return value, err == nil }
  case *ast.ParenExpr: return constantString(x.X, seen)
  case *ast.BinaryExpr:
   if x.Op == token.ADD {
    left, lok := constantString(x.X, seen); right, rok := constantString(x.Y, seen)
    return left + right, lok && rok
   }
  case *ast.Ident:
   if x.Obj != nil {
    switch decl := x.Obj.Decl.(type) {
    case *ast.ValueSpec:
     for i, name := range decl.Names { if name.Name == x.Name && i < len(decl.Values) { return constantString(decl.Values[i], seen) } }
    case *ast.AssignStmt:
     for i, lhs := range decl.Lhs { if id, ok := lhs.(*ast.Ident); ok && id.Name == x.Name && i < len(decl.Rhs) { return constantString(decl.Rhs[i], seen) } }
    }
   }
  }
  return "", false
 }
 add := func(expr ast.Expr) { if value, ok := constantString(expr, map[ast.Expr]bool{}); ok { found[value] = true } }
 isResolution := func(expr ast.Expr) bool {
  switch x := expr.(type) {
  case *ast.Ident: return strings.EqualFold(x.Name, "resolution")
  case *ast.SelectorExpr: return x.Sel.Name == "Resolution"
  }
  return false
 }
 ast.Inspect(file, func(node ast.Node) bool {
  switch x := node.(type) {
  case *ast.KeyValueExpr: if isResolution(x.Key) { add(x.Value) }
  case *ast.AssignStmt:
   for i, lhs := range x.Lhs { if isResolution(lhs) && i < len(x.Rhs) { add(x.Rhs[i]) } }
  case *ast.ValueSpec:
   for i, name := range x.Names { if isResolution(name) && i < len(x.Values) { add(x.Values[i]) } }
  }
  return true
 })
 return found
}

